{"Channel": {"name": "develop-ianmiller-SearchFlow", "channelID": "ch-hflow-a687ca"}, "Message": {"User": {"userId": "eid_9bddb57c", "timestamp": "2026-04-06T23:24:00", "text": "That sounds like a significant issue. @eid_95f6d01c, do you know if they have any solutions or workarounds for this performance problem?", "utterranceID": "20260529-3-ae3cf"}, "Reactions": []}, "ThreadReplies": [], "id": "20260529-3-ae3cf"}
