{"Channel": {"name": "develop-emmamartinez-ProposalForce", "channelID": "ch-force-888914"}, "Message": {"User": {"userId": "eid_48d82563", "timestamp": "2027-02-04T23:50:00", "text": "One more thing, @eid_8a2cd06b. The documentation needs a bit more detail on the changes in session management. Could you update that section? 📚", "utterranceID": "20270205-8-cd841"}, "Reactions": []}, "ThreadReplies": [], "id": "20270205-8-cd841"}
