{"Channel": {"name": "bug-ianjones-ContentForce", "channelID": "ch-force-4901d0"}, "Message": {"User": {"userId": "eid_07cc9100", "timestamp": "2026-10-08T19:53:00", "text": "After reviewing the details, it turns out that this is not a bug that requires fixing.", "utterranceID": "20261008-1-6f97d"}, "Reactions": []}, "ThreadReplies": [], "id": "20261008-1-6f97d"}
