{"Channel": {"name": "bug-hannahmartinez-FeedbackForce", "channelID": "ch-force-2e338c"}, "Message": {"User": {"userId": "slack_admin_bot", "timestamp": "2026-11-24T06:24:00", "text": "@eid_8c71a7a9 joined bug-hannahmartinez-FeedbackForce. Also, @eid_961f0487, @eid_ea95d983, @eid_576f3f62, @eid_84b3cc1f joined via invite.", "utterranceID": "20261124-1-10195"}, "Reactions": []}, "ThreadReplies": [], "id": "20261124-1-10195"}
