{"Channel": {"name": "bug-iangarcia-LeadForce", "channelID": "ch-force-bd5140"}, "Message": {"User": {"userId": "eid_a43a4389", "timestamp": "2026-10-11T01:00:00", "text": "Absolutely, Ian! The schema mismatch in Kafka is a good parallel to our lead scoring issue. I'll dive into their solution and see if we can adapt it to ensure our data schemas align correctly. 🚀", "utterranceID": "20261010-4-38770"}, "Reactions": []}, "ThreadReplies": [], "id": "20261010-4-38770"}
